public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        if (scanner.hasNext()) {
            String placa = scanner.next();
            if (placa.matches("^[A-Z]{3}-[0-9]{4}$")) {
                System.out.println(1);
            } else if (placa.matches("^[A-Z]{3}[0-9][A-Z][0-9]{2}$")) {
